mapper.select:
/* User10Mapper.selectStdWorkUserList */
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
/* SELECT 컬럼 순서 = StdWorkUserRowResult 생성자 인자 순서와 1:1 (record 위치 매핑). */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.NODE_CD AS nodeCd , N.NODE_NM AS nodeNm , U.EMPLOYMENT_TYPE AS employmentType , U.HIRE_DATE AS hireDate , H.WEEK_STD_MINUTES AS weekStdMinutes , H.REASON_CD AS reasonCd , D.SYST_VAL_D_NM AS reasonNm , H.APPLY_STR_DATE AS applyStrDate , H.APPLY_END_DATE AS applyEndDate
FROM TB_USER U
LEFT JOIN TB_SITE_NODE N ON N.CMPNY_CD = U.CMPNY_CD AND N.SITE_CD = U.SITE_CD AND N.NODE_CD = U.NODE_CD
/* 오늘 기준 유효 이력 1건. 시작일이 가장 늦은 행으로 고정(중복 방어). */ LEFT JOIN TB_USER_STD_WORK_HOURS H ON H.CMPNY_CD = U.CMPNY_CD AND H.USER_CD = U.USER_CD AND H.APPLY_STR_DATE = ( SELECT MAX(X.APPLY_STR_DATE) FROM TB_USER_STD_WORK_HOURS X WHERE X.CMPNY_CD = U.CMPNY_CD AND X.USER_CD = U.USER_CD AND X.APPLY_STR_DATE <= DATE_FORMAT(NOW(), '%Y%m%d') AND ( X.APPLY_END_DATE IS NULL OR X.APPLY_END_DATE >= DATE_FORMAT(NOW(), '%Y%m%d') ) )
LEFT JOIN TB_SYST_VAL_D D ON D.SYST_VAL_CD = 'SYS083' AND D.SYST_VAL_D_CD = H.REASON_CD
WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' /* 탈퇴 계정 제외(계약량 관리 대상 아님). 승인대기·거부 계정도 아직 근로자가 아니라 제외. */ AND U.ACCOUNT_STATUS NOT IN ('03', '06', '07') /* 일용직은 소정근로 개념이 없다(고용형태 미지정 NULL 계정은 관리 대상으로 남긴다). */ AND ( U.EMPLOYMENT_TYPE IS NULL OR U.EMPLOYMENT_TYPE != 'DAILY' )
AND EXISTS ( SELECT 1 FROM node_tree NT WHERE NT.CMPNY_CD = U.CMPNY_CD AND NT.SITE_CD = U.SITE_CD AND NT.NODE_CD = U.NODE_CD )
AND U.NODE_CD = #{nodeCd}
AND ( U.USER_ID LIKE CONCAT('%', #{userKeyword}, '%') OR U.USER_NM LIKE CONCAT('%', #{userKeyword}, '%') )
ORDER BY U.USER_NM, U.USER_CD
